'use strict';

function validateState(state) {
  if (state === null || typeof state !== 'object' ||
      typeof state.left !== 'boolean' || typeof state.right !== 'boolean') {
    throw new TypeError('invalid pane state');
  }
}

function createPaneState() {
  return { left: false, right: false };
}

function paneReducer(state, action) {
  validateState(state);
  if (action === null || typeof action !== 'object' || typeof action.type !== 'string') {
    throw new TypeError('invalid action');
  }
  switch (action.type) {
    case 'OPEN_LEFT': return { left: true, right: false };
    case 'OPEN_RIGHT': return { left: false, right: true };
    case 'CLOSE_LEFT': return { ...state, left: false };
    case 'CLOSE_RIGHT': return { ...state, right: false };
    case 'CLOSE_ALL': return { ...state, left: false };
    default: throw new TypeError('unknown action');
  }
}

function getContainerClass(state) {
  validateState(state);
  let result = 'pane-shell';
  if (state.left) result += ' shift-right';
  if (state.right) result += ' shift-left';
  return result;
}

module.exports = { createPaneState, paneReducer, getContainerClass };

