'use strict';
const assert = require('node:assert/strict');
const api = require('./solution');
assert.deepEqual(Object.keys(api).sort(), ['createPaneState', 'getContainerClass', 'paneReducer']);
const { createPaneState, paneReducer, getContainerClass } = api;

const initial = createPaneState();
assert.deepEqual(initial, { left: false, right: false });
assert.equal(getContainerClass(initial), 'pane-shell');
assert.equal(getContainerClass({ left: true, right: false }), 'pane-shell shift-right');
assert.equal(getContainerClass({ left: false, right: true }), 'pane-shell shift-left');
assert.equal(getContainerClass({ left: true, right: true }), 'pane-shell shift-right shift-left');

const actions = [
  ['OPEN_LEFT', { left: true, right: false }],
  ['OPEN_RIGHT', { left: false, right: true }],
  ['CLOSE_LEFT', { left: false, right: false }],
  ['CLOSE_RIGHT', { left: false, right: false }],
  ['CLOSE_ALL', { left: false, right: false }]
];
for (const [type, expected] of actions) {
  const source = { left: false, right: false };
  const action = { type };
  const result = paneReducer(source, action);
  assert.deepEqual(result, expected);
  assert.notStrictEqual(result, source);
  assert.deepEqual(source, { left: false, right: false });
  assert.deepEqual(action, { type });
}
assert.deepEqual(paneReducer({ left: false, right: true }, { type: 'OPEN_LEFT' }), { left: true, right: false });
assert.deepEqual(paneReducer({ left: true, right: false }, { type: 'OPEN_RIGHT' }), { left: false, right: true });
assert.deepEqual(paneReducer({ left: true, right: true }, { type: 'CLOSE_LEFT' }), { left: false, right: true });
assert.deepEqual(paneReducer({ left: true, right: true }, { type: 'CLOSE_RIGHT' }), { left: true, right: false });
assert.deepEqual(paneReducer({ left: true, right: true }, { type: 'CLOSE_ALL' }), { left: false, right: false });

for (const badState of [null, undefined, [], {}, { left: false }, { left: 0, right: false }, { left: false, right: null }]) {
  assert.throws(() => paneReducer(badState, { type: 'CLOSE_ALL' }), TypeError);
  assert.throws(() => getContainerClass(badState), TypeError);
}
for (const badAction of [null, undefined, {}, [], { type: 1 }, { type: 'UNKNOWN' }]) {
  assert.throws(() => paneReducer(initial, badAction), TypeError);
}

